def closure(ids):
 seen=set(); stack=list(ids)
 while stack:
  gid=stack.pop()
  if gid in seen:continue
  seen.add(gid);stack.extend(ALL[gid].get('requires',[]))
 return seen

def add(key,title,title_en,covered,task,task_en,solution,solution_en,cores,sources,checks=None):
 def readable(s):
  s=re.sub(r'(?<=[a-zäöüß])(?=[0-9])',' ',s)
  return re.sub(r'(?<=\d)(µF|µA|µT|µC|nC|pF|keV|MeV|MHz|mm|cm|kg|ms|mA|mV|nF|pC|N|V|T|A|J|s|m)\b',r' \1',s)
 task,task_en,solution,solution_en=map(readable,(task,task_en,solution,solution_en))
 cores=[tuple(readable(x) for x in c) for c in cores]
 ids=[G[i]['id'] for i in covered]
 # Every claimed ordinary goal is true preparation. Keep R transitively minimal.
 req=[i for i in ids if not any(i in closure([j]) for j in ids if j!=i)]
 tags=['GK','LK'] if all('GK' in G[i]['tags'] for i in covered) else ['LK']
 n=len(cores);maximum=4*n;passing=maximum-2
 policy=(f'Bewertung: je Kern 4 Punkte: 2 für den Grundfall und 2 für die im Schritt genannte unabhängige Übertragung'
         f' (bei drei Fällen gilt die ausdrücklich im Schritt genannte Verteilung). Kleine Rechen-, Rundungs- oder Zeichenfehler bei nachweislich richtigem Konzept kosten höchstens 1 Punkt je betroffenem Kern; konsistente Folgefehler nicht doppelt abziehen. '
         f'Bestehen ab {passing}/{maximum}. Jede im Schrittkriterium ausdrücklich genannte fachliche Kernaussage und verlangte Übertragung zählt separat als wesentlich. Fehlt eine solche Kernaussage oder verlangte Übertragung vollständig, oder wird sie durch eine explizite Fehlvorstellung ersetzt, ist die GESAMTPUNKTZAHL unabhängig von anderen Punkten auf höchstens {passing-1} begrenzt. '
         'Eine bloß fehlende Nebenrechnung oder geringfügig ungenaue Skizze ist keine Kernauslassung. Gleichwertige fachlich richtige Lösungswege anerkennen. Die ausgewiesenen Punkte bleiben innerhalb der einzelnen Schritte; die Gesamtgrenze ist anschließend anzuwenden.')
 policy_en=(f'Scoring: 4 points per core, 2 for the base case and 2 for the independent transfer named in the step (use the explicit step allocation for three cases). '
            f'A minor arithmetic, rounding or drawing error with demonstrably correct understanding costs at most 1 point in its core; do not penalize consistent consequential errors twice. Pass at {passing}/{maximum}. '
            f'Every substantive core statement and required transfer explicitly named in a step is separately essential. If any such statement or required transfer is wholly missing or replaced by an explicit misconception, cap the TOTAL at {passing-1}, regardless of other points. '
            'A missing ancillary calculation or slightly imprecise sketch is not a missing core. Accept equivalent valid methods. Apply the total cap after awarding step points.')
 allocations={
  'mri-three-independent-situations':['2P A + 2P C','1P A + 1P B + 2P C1','2P A + 2P C1/C2','2P B + 2P C2'],
  'induction-and-field-line-limits':['2P A + 2P C','1P A + 1P B + 2P C','1P A + 2P B + 1P C','2P B + 2P C']}
 steps=[{'id':f'k{i+1}','points':4,'description':(policy+'\n' if i==0 else '')+('Aufteilung / allocation: '+allocations[key][i]+'. ' if key in allocations else '')+c[0]+' EN: '+c[1]} for i,c in enumerate(cores)]
 taskgoal={
  'id':str(uuid.uuid5(NS,key)), 'title':title,'titleEn':title_en,
  'description':'Die lernende Person kann die folgenden konkreten Fälle selbstständig bearbeiten und ihre fachlichen Entscheidungen begründen: '+', '.join(G[i]['title'] for i in covered)+'.',
  'descriptionEn':'The learner can independently solve and justify the concrete cases concerning '+', '.join(G[i]['titleEn'] for i in covered)+'.',
  'weight':1,'tags':tags+['Practice','Assessment'],'contains':[],'requires':req,
  'dimensionTags':{'framework':'hessen-kc-2024-physics','demandLevel':'AB3','processCompetencies':['PK2_MODELLIEREN','PK3_MATHEMATISIEREN','PK4_KOMMUNIZIEREN'],'guidingIdeas':['LI_FELDER'],'phase':'Q1'},
  'applicability':{'jurisdiction':sorted(set.intersection(*(set(G[i]['applicability']['jurisdiction']) for i in covered)))},
  'examData':{'reviewStatus':'draft','coveredGoalIds':ids,'coveredStrands':['LI_FELDER'],'demandLevels':['AB1','AB2','AB3'],'taskContent':task,'taskContentEn':task_en,'solutionContent':solution+'\n\n'+policy,'solutionContentEn':solution_en+'\n\n'+policy_en,'scoring':{'maxPoints':maximum,'passingPoints':passing,'steps':steps}},
  'phase':'Q1','type':'atomic'}
 assert set(ids)<=closure(req)
 TASKS.append(taskgoal)
 REVIEWS.append({'taskId':taskgoal['id'],'key':key,'status':'draft-author-candidate-not-independent-review','coveredRowIndices':covered,
   'coverageBasis':[{'goalId':G[i]['id'],'profileFingerprint':ROWS[i]['positiveEvidenceProfile']['record']['profileFingerprint'],'requiredExpectationIds':ROWS[i]['positiveEvidenceProfile']['record']['profile']['coverageExpectations']['requiredExpectationIds'],'independentDemonstrationsRequired':ROWS[i]['positiveEvidenceProfile']['record']['profile']['coverageExpectations']['minimumIndependentDemonstrations']} for i in covered],
   'essentialClaims':[{'core':f'k{i+1}','criterionDe':c[0],'criterionEn':c[1], 'counteranswerDe':c[2], 'missingCoreScoreMaximum':passing-1,'minorErrorScore':maximum-1,'minorErrorPasses':maximum-1>=passing} for i,c in enumerate(cores)],
   'sources':[{'url':SOURCES.get(s,s),'use':'Scientific model constraint only; all problem data and formulations are newly authored. No claim of official curriculum provenance.'} for s in sources],
   'authorNumericChecks':checks or [],
   'placementProposal':{'phase':'Q1','rule':'Attach only to the existing task container at the stage where ALL actual requires are already required; do not move ordinary goals or import broad Q1 packages into earlier units. Keep GK/LK applicability of preparation.','requires':req}})

add('magnetisation-two-materials','Prüfungsaufgabe: Magnetisierung über Materialgeschichte erklären','Assessment: Explain magnetisation through material history',[0],
'''**Fall A – Modellprobe.** Drei gleich große Proben besitzen je 12 gleich große, schematisch nur nach rechts oder links orientierte magnetische Momentbeiträge. A: 6 rechts/6 links; B: 8 rechts/4 links; C: 2 rechts/10 links. Bestimme für jede Probe Richtung und relative Stärke der resultierenden Magnetisierung; ordne die erwartete äußere Feldwirkung bei gleicher Geometrie. Erkläre über die Summe der Beiträge und benenne eine Grenze dieses Modells.

**Fall B – neue Materialgeschichte.** Ein Sensor misst in festgelegter gleicher Lage die äußere Feldwirkung zweier Proben (normierte Einheiten; kein äußeres Feld beim Nachher-Messen):

| Probe | vorher | im gleichen äußeren Feld | nach Entfernen |
|---|---:|---:|---:|
| X | 0 | 10 | 0,2 |
| Y | 0 | 10 | 8 |

Erkläre alle drei Phasen beider Proben mit mikroskopischen Momenten. Welche Probe wirkt nachher als Permanentmagnet? Die Aussage „Beide sind permanent, weil im Feld 10 gemessen wurde“ ist zu beurteilen. Sage zusätzlich die Richtung der bleibenden Wirkung von Y voraus, wenn die magnetisierende Feldrichtung umgekehrt wird und Y anschließend entsprechend ummagnetisiert bleibt.''',
'''**Case A – model samples.** Each of three equal samples contains 12 equal schematic magnetic-moment contributions pointing only right or left. A: 6 right/6 left; B: 8 right/4 left; C: 2 right/10 left. Determine direction and relative magnitude of the resultant magnetisation and rank the external field effects for equal geometry. Explain using the sum of contributions and state a model limitation.

**Case B – new material history.** A sensor at the same defined position records an external field effect in normalised units:

| Sample | before | in the same applied field | after removal |
|---|---:|---:|---:|
| X | 0 | 10 | 0.2 |
| Y | 0 | 10 | 8 |

The after measurements contain no applied field. Explain all three stages microscopically and decide which sample acts as a permanent magnet. Evaluate “Both are permanent because both reached 10 in the field.” Predict the direction of Y's remaining effect if the magnetising field is reversed and Y retains the corresponding reversed magnetisation.''',
'''A: Resultierende Momentbeiträge 0, +4, −8; A zeigt näherungsweise keine makroskopische Magnetisierung, B nach rechts, C nach links, mit Beträgen 0:4:8. Gleiche Pfeilzahlen bedeuten keine gleichen Vektorsummen. Die Pfeile repräsentieren kollektive mikroskopische Momente, keine fotografierten Miniaturkompassnadeln. B: Anfangs heben sich Beiträge weitgehend auf; das äußere Feld verstärkt die Vorzugsorientierung in beiden Proben. X verliert diese Ordnung nach Feldentfernung weitgehend, Y behält sie und wirkt als Permanentmagnet. Nur der Nachher-Zustand belegt das. Bei erfolgreicher umgekehrter Magnetisierung bleibt in Y die entgegengesetzte Vorzugs- und äußere Feldrichtung zurück.''',
'''A: resultant contributions are 0, +4 and −8: approximately zero for A, rightward for B, leftward for C, with magnitudes 0:4:8. Equal arrow counts do not imply equal vector sums. The model depicts collective microscopic moments, not photographed tiny compass needles. B: initial contributions largely cancel; the applied field promotes preferred alignment in both. X largely loses that alignment after removal while Y retains it and acts as a permanent magnet. The in-field response alone does not establish permanence. Successfully reversing Y's retained magnetisation reverses its preferred and external-field directions.''',
 [('Vektorsumme und makroskopische Richtung/Stärke in A sowie ihre Verbindung mit der Feldwirkung in B; Modellgrenze ausdrücklich benennen.','Vector sum, macroscopic direction/magnitude in A and field connection in B; explicit model limit.','Alle Proben haben 12 Pfeile, daher gleich starke Magnetisierung.'),('Vorher–während–nachher für beide Materialien und bleibende Vorzugsorientierung einschließlich umgekehrter Magnetisierung in B.','Before/during/after explanation and persistent preferred alignment, including reversal in B.','Im eingeschalteten Feld sind beide gleich stark; daher bleiben beide permanent magnetisch.')],['magnetism'],[{'calculation':'[6-6,8-4,2-10]','expected':[0,4,-8]}])

add('radial-and-graphical-superposition','Prüfungsaufgabe: Radialfelder zeichnen und überlagern','Assessment: Draw and superimpose radial fields',[4,9],
'''**Material:** In einer Ebene liegen Punktladungen bei L=(−a,0) und R=(+a,0). Beide tragen zunächst +Q. M=(0,0), P=(0,a). a>0. Zeichne mit einem gemeinsamen frei gewählten Pfeilmaßstab; gleiche Abstände bedeuten gleiche Einzelbeträge.

**A:** Skizziere das radiale Feld einer einzelnen negativen Punktladung, vergleiche die Beträge in Abständen a, 2a und 3a und erkläre die Abnahme geometrisch. Konstruiere dann die beiden Einzelvektoren und die Resultierende der +Q/+Q-Anordnung in M und P mittels Parallelogramm oder Spitze-an-Schaft. Begründe, welche Komponenten verschwinden.

**B:** Nur R wird zu −Q. Sage zuerst die Änderungen in M und P voraus und konstruiere danach alle Einzelvektoren und Resultierenden im selben Maßstab. Zwei neue kugelsymmetrische Körper mit Radien a und 2a tragen je +Q: Vergleiche ihre Felder am gemeinsamen äußeren Punkt mit Zentrumabstand 3a. Prüfe, ob daraus auch gleiche Innenfelder oder das Außenfeld einer beliebigen unsymmetrischen Ladungsverteilung folgen.''',
'''**Material:** Point charges L=(−a,0) and R=(+a,0) lie in a plane, initially both +Q. M=(0,0), P=(0,a), a>0. Choose one common arrow scale; equal distances imply equal individual magnitudes.

**A:** Sketch the radial field of one negative point charge. Compare magnitudes at a, 2a and 3a and justify their geometric scaling. Then construct each contribution and the resultant for +Q/+Q at M and P by a parallelogram or head-to-tail method. Explain cancelled components.

**B:** Change only R to −Q. Predict changes at M and P before constructing the contributions and resultants at the same scale. Two new spherical charge distributions of radii a and 2a each carry +Q: compare their fields at a common exterior point 3a from their centres. Decide whether this establishes equal interior fields or the field of an arbitrary nonspherical distribution.''',
'''Einzelne negative Ladung: radial nach innen, Beträge E(a):E(2a):E(3a)=1:1/4:1/9. Dieselbe Flussmenge verteilt sich auf Kugelflächen 4πr²; Linien sind qualitative Darstellung, keine Stofffäden. A: In M gleich große entgegengesetzte waagerechte Beiträge, Summe null. In P Beiträge schräg nach rechts oben und links oben; horizontale Komponenten verschwinden, vertikale addieren nach oben. B: In M zeigen beide Beiträge nach rechts, daher doppelte Einzelstärke. In P Beitrag von L rechts oben, Beitrag zu R rechts unten; vertikale Komponenten verschwinden, horizontale addieren nach rechts. Im gemeinsamen Außenraum der beiden Kugeln gilt bei gleicher Gesamtladung das gleiche radiale Außenfeld, hier nach außen. Die Aussage benötigt Kugelsymmetrie und r außerhalb beider Körper; sie legt Innenfelder oder unsymmetrische Felder nicht fest.''',
'''A negative point charge has an inward radial field, with E(a):E(2a):E(3a)=1:1/4:1/9 because equal flux spreads across spherical areas 4πr². Field lines are qualitative representations. A: at M equal opposing horizontal contributions cancel. At P the contributions point up-right and up-left: horizontal components cancel and vertical components add upward. B: at M both point right and add to twice either contribution. At P the contributions point up-right and down-right: vertical components cancel and horizontal ones add rightward. The spherical bodies produce equal outward fields at the common exterior radius because total charge is equal. This needs spherical symmetry and exterior points and says nothing conclusive about interiors or arbitrary nonspherical distributions.''',
 [('Radiale Richtung und geometrische 1/r²-Begründung in A; gültiger gemeinsamer Kugel-Außenraum und explizite Innenraum-/Unsymmetriegrenze in B.','Radial direction and geometric inverse-square argument in A; common spherical exterior and explicit interior/nonsymmetry limit in B.','Doppelter Abstand halbiert E; gleiche Gesamtladung erzwingt überall gleiche Felder.'),('Grafische Addition mit Einzelvektoren, gemeinsamem Maßstab und korrekten Resultierenden in M/P in beiden unabhängigen Vorzeichenfällen.','Graphical addition with individual arrows, common scale and correct resultants at M/P in both charge-sign cases.','Zwei gleich starke Felder addieren sich in M immer zu doppeltem Betrag.'),('Qualitative Vorhersage vor Konstruktion und komponentenbezogene Symmetriebegründung für beide Anordnungen.','Prediction before construction and component-specific symmetry reasoning for both configurations.','Symmetrische Lage bedeutet auch beim Dipol überall Feld null.')],['electric-field','gauss-field'],[{'calculation':'[1,1/2**2,1/3**2]','expected':[1,0.25,1/9]}])

add('electric-particle-paths','Prüfungsaufgabe: Elektrische Feldkraft, Bahn und Energie verknüpfen','Assessment: Connect electric force, trajectory and energy',[5],
'''Alle Felder sind homogen; Gravitation und andere Kräfte werden vernachlässigt, Geschwindigkeiten sind nichtrelativistisch. x zeigt rechts, y oben. E=2,0·10³ N/C zeigt nach +x. Für alle Fälle sind q-Betrag=2,0 nC und m=1,0·10⁻⁶ kg.

**A:** Ein positives Teilchen startet mit v nach +y. Zeichne E, F und a sowie eine qualitative Bahn. Berechne F und a. Nach einer Bewegung um Δx=+0,030 m: bestimme ΔE_pot und ΔE_kin und erkläre ihre Vorzeichen. Ein zweites positives Teilchen startet geradlinig nach −x: beschreibe Abbremsen, mögliche Umkehr und die Energieentwicklung vor der Umkehr.

**B:** Ein negatives Teilchen startet mit v nach +x und nach +y (beide Komponenten positiv). Zeichne Anfangskraft und Bahnkrümmung; verfolge die x-Komponente bis zur möglichen Umkehr. Beurteile kinetische und elektrische potenzielle Energie zunächst solange es nach +x läuft und danach, wenn es nach −x läuft. Sage zuletzt die geänderte Bahn bei vollständiger Feldumkehr voraus; begründe konsistent über qE und Feldarbeit.''',
'''All fields are uniform; ignore gravity and other forces and use nonrelativistic motion. x is right, y up. E=2.0×10³ N/C points +x. In every case |q|=2.0 nC and m=1.0×10⁻⁶ kg.

**A:** A positive particle initially moves +y. Draw E, F, a and a qualitative trajectory. Calculate F and a. After Δx=+0.030 m determine ΔE_pot and ΔE_kin and explain their signs. A second positive particle initially moves −x: describe slowing, possible reversal and energy changes before reversal.

**B:** A negative particle starts with positive x and y velocity components. Draw its initial force and curvature; follow the x component to possible reversal. Discuss kinetic and electric potential energy before reversal while moving +x and afterwards while moving −x. Finally predict the trajectory change on reversing the entire electric field using qE and field work consistently.''',
'''A: F=qE=4,0·10⁻⁶ N nach rechts, a=4,0 m/s² nach rechts. Gleichförmige y-Bewegung plus gleichmäßig beschleunigte x-Bewegung ergibt eine nach rechts gekrümmte Parabel. ΔE_kin=W_F=qEΔx=+1,2·10⁻⁷ J, ΔE_pot=−1,2·10⁻⁷ J. Das anfangs nach links bewegte positive Teilchen wird abgebremst (K sinkt, E_pot steigt), kann vx=0 erreichen und danach nach rechts beschleunigen. B: Negative Ladung hat F/a nach links, konstantes vy und nach links gekrümmte Parabel. Anfangs ist F·v<0: K sinkt und E_pot steigt; bei vx=0 ist K wegen vy nicht insgesamt null. Danach ist F·v>0: K steigt und E_pot sinkt. Feldumkehr kehrt F/a und die Krümmung um; bei ursprünglichem positivem vx gewinnt die negative Ladung nun kinetische Energie. In allen Fällen bleibt K+E_pot erhalten.''',
'''A: F=qE=4.0×10⁻⁶ N and a=4.0 m/s² rightward. Uniform y motion plus constant x acceleration gives a right-curving parabola. ΔK=qEΔx=+1.2×10⁻⁷ J and ΔE_pot=−1.2×10⁻⁷ J. A positive particle moving left slows, loses K and gains potential energy until reversal, then accelerates rightward. B: force/acceleration point left; vy stays constant and the parabola curves left. While vx>0, F·v<0 so K decreases and potential energy increases. At vx=0 total K remains nonzero because vy persists. After vx<0 K increases and potential energy decreases. Reversing E reverses force and curvature; the original negative particle moving +x then gains K. K+E_pot is conserved throughout.''',
 [('F=qE mit Ladungsvorzeichen und konsistente Kraft-/Beschleunigungsrichtungen in A und B einschließlich Feldumkehr.','F=qE with charge sign and consistent force/acceleration directions in A/B and field reversal.','Das negative Teilchen beschleunigt immer in Feldrichtung.'),('Anfangsbewegung und konstante Kraft zu Bahnformen kombinieren, einschließlich Abbremsen/Umkehr und erhaltener Querbewegung im Transfer.','Combine initial motion and constant force into paths, including slowing/reversal and persistent transverse motion.','Bei vx=0 steht das schräg gestartete Teilchen vollständig still.'),('Feldarbeit, gegenläufige Energieänderungen und Gesamtenergie für die konkrete A-Rechnung sowie beide Bewegungsphasen in B.','Field work, opposite energy changes and total energy for A calculation and both phases of B.','Im E-Feld steigt die kinetische Energie unabhängig von Bewegungsrichtung immer an.')],['electric-field'],[{'calculation':'2e-9*2e3','expected':4e-6,'unit':'N'},{'calculation':'2e-9*2e3*.03','expected':1.2e-7,'unit':'J'}])

add('lorentz-and-controlled-orbits','Prüfungsaufgabe: Lorentzkraft und kontrollierte Bahnenvergleiche','Assessment: Lorentz force and controlled orbit comparisons',[8,25],
'''Das rechtshändige System hat x nach rechts, y nach oben und z aus dem Blatt. Ein homogenes Magnetfeld B=0,20 T zeigt nach −z. Andere Kräfte fehlen; alle Geschwindigkeiten sind nichtrelativistisch. |q|=3,0 nC, v=4,0·10³ m/s.

**A:** Zwei Spuren starten nach +x; A krümmt zunächst nach +y, B nach −y. Erschließe beide Ladungsvorzeichen, zeichne die Kräfte und berechne ihren Betrag für senkrechten Eintritt. Erkläre den konstanten Geschwindigkeitsbetrag. Eine weitere positive Ladung tritt unter 30° zu B ein: berechne den momentanen Kraftbetrag. Vergleiche mit parallelem Eintritt und erkläre Gerade beziehungsweise Kreis für die Grenzfälle 0° und 90°.

**B:** Die Referenzbahn hat Radius r. Für vier voneinander unabhängige Läufe bleiben alle nicht ausdrücklich geänderten Größen gleich: (1) 2v, (2) 2B, (3) 2m bei gleichem q, (4) umgekehrtes B. Sage Radiusänderung, anfängliche Kraftrichtung und Energieentwicklung voraus; gib bei (4) den geänderten Umlaufsinn an. Eine unbekannte fünfte Bahn hat 2r, aber m und v wurden beide nicht dokumentiert: prüfe die Behauptung „die Masse ist sicher doppelt so groß“. Wiederhole die Grenzfallüberlegung bei parallelem Eintritt nach Feldumkehr.''',
'''Use a right-handed system with x right, y up, z out of the page. A uniform B=0.20 T points −z. No other forces act and all speeds are nonrelativistic. |q|=3.0 nC, v=4.0×10³ m/s.

**A:** Two tracks start +x; A initially curves +y and B −y. Infer both charge signs, draw forces and calculate their perpendicular-entry magnitudes. Explain constant speed. Another positive charge enters at 30° to B: calculate its instantaneous force magnitude. Compare parallel entry and explain straight/circular motion for the limiting 0°/90° cases.

**B:** A reference orbit has radius r. Independent runs change only (1) v to 2v, (2) B to 2B, (3) m to 2m at fixed q, (4) the sign of B. Predict radius changes, initial force direction and energy evolution; for (4) describe circulation reversal. An undocumented fifth run has radius 2r with both m and v unknown: assess “the mass must have doubled.” Repeat the parallel-entry limit after field reversal.''',
'''A: +x×(−z)=+y, daher Spur A positiv, B negativ. F_90=|q|vB=2,4·10⁻⁶ N, F_30=1,2·10⁻⁶ N; parallel F=0. Rein magnetische Kraft steht senkrecht zu v, verrichtet keine Arbeit, ändert nur Richtung. 0° liefert Gerade, 90° Kreis unter den genannten Annahmen. B: aus r=mv/(|q|B) folgen 2r,r/2,2r,r. Für ein positives Referenzteilchen bleibt die anfängliche Kraft in (1)–(3) nach +y, in (4) nach −y; negative Ladung jeweils umgekehrt. Reine Feldumkehr ändert Umlaufsinn, nicht Radiusbetrag oder Energie; alle Läufe erhalten jeweils ihren Geschwindigkeitsbetrag. In (1) ist die anfängliche kinetische Energie gegenüber der Referenz vierfach, in (3) doppelt, sie wird aber nicht durch das Magnetfeld erhöht. Unbekannte m und v erlauben nur das Produkt mv bei bekanntem |q|B; doppelte Masse ist nicht eindeutig. Parallel oder antiparallel bleibt F=0 auch nach Feldumkehr.''',
'''A: +x×(−z)=+y, so A is positive and B negative. F_90=2.4×10⁻⁶ N, F_30=1.2×10⁻⁶ N, parallel F=0. A magnetic force is perpendicular to v, does no work and changes direction only. With the stated assumptions 0° gives a straight path and 90° a circle. B: r=mv/(|q|B) gives 2r,r/2,2r,r. For a positive reference particle initial force is +y in (1)–(3), −y in (4); reverse these for negative charge. Field reversal reverses circulation without changing radius magnitude or K; each run preserves its own speed. Run (1) initially has four times the reference K and (3) twice, but B supplies no energy. Unknown m and v do not determine mass separately. Parallel/antiparallel motion stays force-free after field reversal.''',
 [('Betragsformel mit tatsächlichem Winkel einschließlich 30° und 0°/90°; entsprechende Grenzfälle auch bei Feldumkehr.','Magnitude formula with actual angle including 30° and 0°/90°, repeated after field reversal.','Der Winkel darf immer 90° gesetzt werden, daher auch parallel F=|q|vB.'),('Ladungsvorzeichen aus bekannter v/B-Richtung und Krümmung erschließen; Kreuzprodukt und Richtungsumkehr im neuen Fall.','Infer charge from known v/B and curvature; cross product and reversal in transfer.','Die obere Spur ist negativ, weil Elektronen immer nach oben abgelenkt werden.'),('Magnetkraft als senkrechte, arbeitsfreie Kraft und begründete Gerade/Kreis bei ausgeschlossenen weiteren Kräften in beiden Fällen.','Perpendicular work-free force and justified straight/circular limits without other forces in both cases.','Die Kreisbahn zeigt, dass das Magnetfeld den Geschwindigkeitsbetrag ständig erhöht.'),('Kontrollierte m/v/B-Radiusvergleiche einzeln begründen, Konstanten nennen und Mehrdeutigkeit bei unbekanntem m und v ausdrücklich begrenzen.','Explain controlled m/v/B comparisons, name constants and limit inference when m/v are both unknown.','Aus 2r folgt auch bei unbekanntem v zwingend 2m.')],['magnetic-motion'],[{'calculation':'3e-9*4e3*.2','expected':2.4e-6,'unit':'N'},{'calculation':'3e-9*4e3*.2*math.sin(math.pi/6)','expected':1.2e-6,'unit':'N'}])

add('quantitative-circular-orbits','Prüfungsaufgabe: Radius und Umlaufzeit unabhängig bestimmen','Assessment: Determine orbit radius and period independently',[2],
'''Andere Kräfte fehlen. Ein homogenes Feld B=0,10 T zeigt in das Blatt. Ein Proton (m_p=1,67·10⁻²⁷ kg, q=+1,60·10⁻¹⁹ C) und ein Elektron (m_e=9,11·10⁻³¹ kg, q=−1,60·10⁻¹⁹ C) treten beide nach rechts mit v=1,00·10⁶ m/s senkrecht zu B ein.

**A:** Leite r und T aus Lorentz- und Zentripetalkraft her, prüfe die SI-Einheiten und berechne beide Größen für beide Teilchen. Konstruiere Umlaufsinne und erkläre die Energieentwicklung.

**B:** Ein neues Ion hat 2m_p und +2e. Vergleiche bei gleichem v und B Radius und Umlaufzeit mit dem Proton. Prüfe anschließend jeweils getrennt 2v und 2B für dieses Ion. Ein weiterer Datensatz nennt v=0,95c, ein anderer einen Eintrittswinkel von 40° zu B: begrenze ausdrücklich, welche der hergeleiteten einfachen Kreisformeln in diesen Fällen unmittelbar benutzt werden dürfen.''',
'''Ignore other forces. A uniform B=0.10 T points into the page. A proton (m_p=1.67×10⁻²⁷ kg, q=+1.60×10⁻¹⁹ C) and electron (m_e=9.11×10⁻³¹ kg, q=−1.60×10⁻¹⁹ C) enter rightward at v=1.00×10⁶ m/s, perpendicular to B.

**A:** Derive r and T from magnetic and centripetal forces, check SI units and calculate both quantities for each particle. Construct circulation directions and explain energy evolution.

**B:** A new ion has mass 2m_p and charge +2e. At equal v/B compare r/T with the proton. Then separately test 2v and 2B for that ion. Other data specify v=0.95c or an entry angle of 40° to B: state explicitly which simple circular formulas can be used directly and which model assumptions fail.''',
'''|q|vB=mv²/r ergibt r=mv/(|q|B). T=2πr/v=2πm/(|q|B). Mit 1 T=kg/(C s) folgen m beziehungsweise s. Proton: r=0,104375 m, T=6,558·10⁻⁷ s; Elektron: r=5,69375·10⁻⁵ m, T=3,577·10⁻¹⁰ s. Proton anfänglich nach oben gekrümmt, Elektron nach unten; vom Betrachter aus gegen bzw. mit Uhrzeigersinn. Der Geschwindigkeitsbetrag und K bleiben konstant. B: 2m_p/(2e) ist gleich m_p/e, daher gleiche r/T wie Proton. Doppeltes v verdoppelt r, T bleibt; doppeltes B halbiert beide. Bei 0,95c ist die nichtrelativistische Beziehung p=mv nicht tragfähig. Bei 40° entsteht eine Schraubenbahn; der Radius verwendet nur v_perp, die volle Bahn ist kein Kreis. Die nichtrelativistische Kreisperiodendauer kann für die Querbewegung gelten, aber r=mv/(|q|B) mit Gesamt-v nicht. Voraussetzung: homogenes Feld, v≪c und keine weiteren Kräfte.''',
'''|q|vB=mv²/r gives r=mv/(|q|B); T=2πr/v=2πm/(|q|B). Using 1 T=kg/(C s) yields metres and seconds. Proton: r=0.104375 m, T=6.558×10⁻⁷ s. Electron: r=5.69375×10⁻⁵ m, T=3.577×10⁻¹⁰ s. The proton bends upward/counterclockwise on the page, electron downward/clockwise. Speed and K remain constant. B: the new ion has the same m/|q| and thus the same r/T. Doubling v doubles r but preserves T; doubling B halves both. At 0.95c p=mv is inadequate. At 40° the full path is helical and only v_perp determines transverse radius; the nonrelativistic transverse period may remain applicable but the full-v circle formula does not. Uniform B, low speed and no other forces are essential assumptions.''',
 [('Kraftbilanz und Herleitung beider Formeln mit Einheiten; arbeitsfreie Kreisbewegung in A und begründete Grenzen in B.','Force balance, both derivations and units; work-free motion in A and justified model limits in B.','T wird nur geraten; im Magnetfeld nimmt K pro Umlauf zu.'),('Konkrete r/T-Werte für beide Teilchen und getrennte m/|q|-, v- und B-Skalierungen im unabhängigen Ionenfall.','Numerical r/T for both particles and separate m/|q|, v and B scaling in the independent ion case.','Bei doppelter Geschwindigkeit verdoppeln sich r und T.'),('Umlaufsinn aus Ladungsvorzeichen und Feldrichtung; relativistischen und schrägen Eintritt ausdrücklich vom einfachen Vollkreis-Modell abgrenzen.','Circulation from charge/B directions and explicit relativistic/oblique-entry limits.','Auch bei 0,95c und 40° gilt unverändert r=mv/(|q|B) mit Gesamtgeschwindigkeit.')],['magnetic-motion'],[{'calculation':'1.67e-27*1e6/(1.6e-19*.1)','expected':.104375,'unit':'m'},{'calculation':'2*math.pi*1.67e-27/(1.6e-19*.1)','expected':2*math.pi*1.67e-27/(1.6e-19*.1),'unit':'s'},{'calculation':'9.11e-31*1e6/(1.6e-19*.1)','expected':5.69375e-5,'unit':'m'}])

add('oblique-magnetic-entry','Prüfungsaufgabe: Schraubenbahnen aus Komponenten vorhersagen','Assessment: Predict helical motion from components',[6],
'''Rechtshändiges xyz-System; B zeigt nach +z. Homogenes Feld, keine anderen Kräfte, v≪c. Ein positives Teilchen hat anfangs v=(3,0;0;4,0)·10⁴ m/s.

**A:** Konstruiere v_parallel und v_perp, Anfangskraft und eine räumliche Bahnskizze. Erkläre, welche Komponente Radius, Achse und Vorschub pro Umlauf bestimmt. Vergleiche ohne Neuberechnung der Kraft die Grenzfälle (0;0;5,0)·10⁴ m/s und (5,0;0;0)·10⁴ m/s.

**B:** Ein negatives Teilchen tritt bei gleichem Geschwindigkeitsbetrag unter 30° statt 90° zu B ein. Vergleiche Bahnform, senkrechten Anteil, Radius und Vorschub mit seinem senkrechten Eintritt. Danach werden getrennt (i) nur B und (ii) nur v_parallel umgekehrt. Sage jeweils Umlaufsinn, Vorschubrichtung, Radius und Energieentwicklung vorher. Definiere den Umlaufsinn durch die Anfangskraft statt durch eine unklare Blickrichtung.''',
'''Use a right-handed xyz system; B points +z. The field is uniform, no other forces act, and v≪c. A positive particle starts at v=(3.0,0,4.0)×10⁴ m/s.

**A:** Construct parallel/perpendicular velocity components, initial force and a spatial trajectory. Explain which component determines radius, axis and advance per turn. Compare limiting velocities (0,0,5.0)×10⁴ and (5.0,0,0)×10⁴ m/s.

**B:** A negative particle of fixed speed enters at 30° instead of 90° to B. Compare trajectory, perpendicular component, radius and advance with perpendicular entry. Then separately reverse (i) B only and (ii) v_parallel only. Predict circulation, advance direction, radius and energy. Define circulation by its initial force rather than an unspecified viewing direction.''',
'''A: v_parallel=(0;0;4,0)·10⁴, v_perp=(3,0;0;0)·10⁴ m/s. Für q>0 gilt +x×+z=−y, also Anfangskraft −y. Kreisbewegung in xy überlagert mit gleichförmigem +z-Vorschub ergibt Helix; Radius folgt v_perp, Vorschub pro Umlauf v_parallel T. Reine Parallelbewegung Gerade, reine Querbewegung Kreis. B: v_perp=v sin30°=v/2, v_parallel=√3v/2; Helix statt Kreis, Radius halbiert, neuer +z-Vorschub. Für q<0 und anfängliches v_perp nach +x zeigt Kraft zunächst +y. Nur B-Umkehr macht daraus −y, also anderen Umlaufsinn; physikalisches v_parallel und Vorschub bleiben in ihrer Raumrichtung gleich, Radiusbetrag bleibt. Nur v_parallel-Umkehr kehrt Vorschub um, nicht Umlaufsinn oder Radius. Der Betrag v und kinetische Energie bleiben in jedem Lauf konstant; Feldlinien sind keine materiellen Führungen.''',
'''A: v_parallel=(0,0,4.0)×10⁴, v_perp=(3.0,0,0)×10⁴ m/s; +x×+z=−y gives the positive particle's initial force. Circular xy motion plus uniform +z advance produces a helix. Radius depends on v_perp, advance per turn on v_parallel T. Parallel-only motion is straight, perpendicular-only motion circular. B: v_perp=v/2 and v_parallel=√3v/2 give a helix, half the radius and nonzero +z advance. A negative particle with perpendicular velocity +x initially has force +y. Reversing B reverses force/circulation but preserves physical advance direction and radius magnitude. Reversing only v_parallel reverses advance without changing circulation/radius. Speed and K stay constant; field lines are not material guides.''',
 [('Vektorzerlegung relativ zu B in A und geänderter Winkel in B, mit Zuordnung der konstanten und gekrümmten Komponenten.','Velocity decomposition relative to B in A and new angle B, assigning constant/curved components.','Die parallele Komponente wird durch die Lorentzkraft gebremst.'),('Gerade, Kreis und Helix einschließlich Radius/Achse/Vorschub aus den jeweiligen Komponenten, im neuen 30°-Fall.','Straight/circular/helical paths and component-based radius/axis/advance, including 30° transfer.','Bei 30° bleibt der Radius gleich, weil der Gesamtbetrag v gleich ist.'),('Getrennte Wirkung von Ladung, B-Umkehr und v_parallel-Umkehr auf Umlaufsinn und Vorschub bei erhaltener Energie.','Separate effects of charge, B reversal and parallel-velocity reversal on circulation/advance with conserved K.','B-Umkehr kehrt stets auch die Vorschubrichtung und die Energie um.')],['magnetic-motion'],[{'calculation':'math.hypot(3e4,4e4)','expected':5e4,'unit':'m/s'},{'calculation':'math.sin(math.pi/6)','expected':.5}])

add('mass-spectrometer-functions','Prüfungsaufgabe: Ein Massenspektrometer funktional auswerten','Assessment: Interpret a mass spectrometer functionally',[3],
'''Rechtshändiges System: x rechts, y oben, z aus dem Blatt. Das idealisierte Gerät besitzt (1) eine Ionenquelle mit elektrischem Beschleunigungsspalt, (2) einen Geschwindigkeitsfilter, (3) ein reines homogenes Analysiermagnetfeld und Detektoren. Alle Teilchen bewegen sich nichtrelativistisch.

**A:** Positive Ionen laufen nach +x. Im Filter zeigt B_F in das Blatt (−z), E nach unten (−y); nur geradlinig durchlaufende Ionen gelangen weiter. Erkläre Funktionen und Kräfte aller drei Bereiche; verwende bei Bedarf v=E/B_F und r=mv/(|q|B_A). Im Analysierfeld B_A ebenfalls nach −z treten Ionen I(m,+e), II(2m,+e) und III(2m,+2e) mit gleicher ausgewählter Geschwindigkeit ein. Zeichne anfängliche Ablenkungsrichtungen, ordne die Radien und benenne, welche Ionen dieselbe Detektorposition haben können.

**B:** Die Quelle liefert nun negative Ionen gleicher Massen/Ladungsbeträge. Welche elektrischen Polungen müssen angepasst werden, damit sie in gleicher Richtung beschleunigt werden? Kann der unveränderte Geschwindigkeitsfilter dieselbe Geschwindigkeit auswählen? Begründe beide Kräfte. Kehre zusätzlich nur das Analysierfeld um und sage Auftreffseite und Radiusverhältnisse voraus. Beurteile die Aussage „Ein einzelner Auftreffort misst immer die Masse eindeutig“.''',
'''Use a right-handed system: x right, y up, z out of the page. An idealised device contains (1) an ion source and electric acceleration gap, (2) a velocity selector, (3) a pure uniform analysing magnetic field and detectors. Motion is nonrelativistic.

**A:** Positive ions move +x. In the selector B_F points into the page (−z), E downward (−y); only undeflected ions continue. Explain each region's functions and forces; you may use v=E/B_F and r=mv/(|q|B_A). In analyser B_A also −z, ions I(m,+e), II(2m,+e), III(2m,+2e) enter at the same selected speed. Draw initial deflection directions, rank radii and identify possible coincident detector positions.

**B:** The source now produces negative ions of the same masses and charge magnitudes. Which accelerating electric polarity must change to accelerate them in the same direction? Can the unchanged velocity selector pass the same speed? Explain both forces. Additionally reverse only the analysing field and predict detector side and radius ratios. Assess “A single detector location always measures mass uniquely.”''',
'''A: Elektrisches Feld beschleunigt durch Arbeit; Magnetfeld führt/krümmt ohne Energiegewinn. Im Filter positive elektrische Kraft −y und magnetische Kraft +y kompensieren sich bei v=E/B_F. Im Analysierfeld wirkt +y-Kraft; Radien I:II:III=1:2:1. I und III sind ohne zusätzliche Ladungsinformation nicht unterscheidbar: gemessen wird bei gleichem v/B das Verhältnis m/|q|, mit Umlaufsinn Information über Vorzeichen. B: Beschleunigungsspalt elektrisch umpolen, damit qE weiterhin +x wirkt. Im unveränderten Filter kehren beide Kräfte um, bleiben aber bei derselben v betragsgleich entgegengesetzt; Filter muss nicht umgepolt werden. Negative Ionen im unveränderten Analysierfeld krümmen nach −y; zusätzliche B_A-Umkehr krümmt wieder nach +y. Radiusverhältnisse 1:2:1 bleiben. Ein Auftreffort legt ohne q und bekannte Feld-/Geschwindigkeitsbedingungen die Masse nicht eindeutig fest.''',
'''A: Electric fields supply kinetic energy; magnetic fields bend without work. In the selector positive electric force is −y and magnetic force +y; they cancel at v=E/B_F. The analyser initially deflects +y. Radius ratios I:II:III=1:2:1, so I and III may coincide: at fixed v/B the geometry determines m/|q|, with direction also identifying charge sign. B: reverse the accelerating gap polarity so qE remains +x. Both selector forces reverse, still balancing at the same speed, so its fields need no reversal. Negative ions in the original analyser bend −y; reversing only B_A restores +y deflection. Radius ratios remain 1:2:1. A detector position alone cannot determine mass without charge and known field/speed conditions.''',
 [('Funktionen von Beschleunigung, Geschwindigkeitsauswahl und magnetischer Analyse mit Kraft-/Energiewirkung in A sowie veränderte Polung in B.','Functions of acceleration, selection and magnetic analysis with force/energy roles in A and changed polarity in B.','Das Magnetfeld beschleunigt die Ionen energetisch; das E-Feld sortiert nur ihre Masse.'),('Ladungsvorzeichen, v×B und entgegengesetzte Filterkräfte in beiden unabhängigen Vorzeichenfällen; Analysefeldumkehr korrekt.','Charge sign, v×B and opposing selector forces in both charge cases; correct analyser reversal.','Bei negativen Ionen wirken im unveränderten Filter beide Kräfte nach oben.'),('m/|q|-Trennung, 1:2:1-Radien und Mehrdeutigkeit gleicher Detektororte samt gültigen konstanten Bedingungen, auch im neuen Fall.','m/|q| separation, 1:2:1 radii and detector ambiguity under controlled conditions in both cases.','Ion III hat doppelte Masse und muss daher trotz doppelter Ladung getrennt von I auftreten.')],['spectrometer'],[{'calculation':'[1/1,2/1,2/2]','expected':[1,2,1]}])

add('fine-beam-indirect-measurement','Prüfungsaufgabe: Aus dem Fadenstrahlrohr auf |e|/m schließen','Assessment: Infer |e|/m from a fine-beam tube',[7],
'''**Material:** Eine Spulenkalibrierung lautet B=kI mit k=0,500 mT/A. U und I werden eingestellt und an Messgeräten kontrolliert; der Radius wird an der leuchtenden Spur abgelesen. Anfangsgeschwindigkeit vor der Beschleunigung wird vernachlässigt, Strahl senkrecht zum homogenen B, keine anderen Kräfte, nichtrelativistisch.

| Lauf | U | I | abgelesener r |
|---|---:|---:|---:|
| A | 200 V | 2,00 A | 4,77 cm |
| B | 450 V | 2,00 A | 7,15 cm |

**A:** Unterscheide eingestellte, direkt gemessene und modellabhängig erschlossene Größen (B, v, |e|/m und m eingeschlossen). Leite aus elektrischer Beschleunigungsenergie und Kreisbewegung |e|/m=2U/(B²r²) her und werte Lauf A mit Einheit aus.

**B:** Sage den Radiusfaktor bei U=450 V gegenüber A voraus und prüfe mit Lauf B unabhängig denselben Verhältniswert. Beurteile „Aus der sichtbaren Spur wird die Elektronenmasse direkt abgelesen“. Erst jetzt wird unabhängig |e|=1,602·10⁻¹⁹ C bereitgestellt: bestimme m und erläutere die zusätzliche Informationsquelle. Was ändert sich am Radius bei doppeltem I und sonst gleichen Werten?''',
'''**Material:** Coil calibration B=kI, k=0.500 mT/A. U and I are set and monitored with meters; radius is read from the luminous trace. Neglect initial speed before acceleration; the beam is perpendicular to uniform B, no other forces, nonrelativistic.

| Run | U | I | measured r |
|---|---:|---:|---:|
| A | 200 V | 2.00 A | 4.77 cm |
| B | 450 V | 2.00 A | 7.15 cm |

**A:** Distinguish set, directly measured and model-inferred quantities, including B, v, |e|/m and m. Derive |e|/m=2U/(B²r²) from acceleration energy and circular motion and evaluate A with units.

**B:** Predict the radius factor at 450 V and independently evaluate the ratio using B. Assess “The luminous track directly displays electron mass.” Only now an independently known |e|=1.602×10⁻¹⁹ C is supplied: determine m and explain the added information. Predict the radius when I doubles with all other settings fixed.''',
'''U/I sind eingestellt und instrumentell kontrolliert, r ist geometrisch gemessen, B aus I/Kalibrierung erschlossen; v und Verhältnis sind modellabhängig, m benötigt zusätzlich unabhängiges e. |e|U=mv²/2 und |e|vB=mv²/r liefern |e|/m=2U/(B²r²). B=1,00 mT. A: 1,758·10¹¹ C/kg. Radius wächst bei gleichem B wie √U: Faktor √(450/200)=1,5, vorhergesagt 7,155 cm. B ergibt 1,761·10¹¹ C/kg; Rundungsabweichung plausibel. m≈1,602·10⁻¹⁹/(1,758·10¹¹)=9,11·10⁻³¹ kg. Die Daten ohne unabhängiges e trennen Ladung und Masse nicht. Doppelter I verdoppelt B, halbiert r bei gleichem U. Sichtbar ist eine Spur, keine direkte Massenanzeige.''',
'''U/I are set and checked instrumentally; r is measured geometrically; B is inferred from current/calibration, and v and |e|/m are model-dependent. m also needs independent e. Combining |e|U=mv²/2 with |e|vB=mv²/r gives |e|/m=2U/(B²r²). B=1.00 mT; run A gives 1.758×10¹¹ C/kg. At fixed B radius scales as √U, hence factor 1.5 and 7.155 cm. B gives 1.761×10¹¹ C/kg, consistent within rounding. Independent e yields m≈9.11×10⁻³¹ kg. The tube data alone do not separate charge and mass. Doubling I doubles B and halves r at fixed U. A visible trajectory is not a direct mass reading.''',
 [('Eingestellt/gemessen/erschlossen über vollständige Kette in A unterscheiden und direkte Massenbehauptung im neuen Fall begrenzen.','Distinguish set/measured/inferred through the full chain in A and reject direct-mass claim in B.','B, e und m werden alle direkt an der Spur abgelesen.'),('Energie- und Kraftbilanz zur spezifischen Ladung mit Einheit kombinieren; unabhängige U- und I-Variationen vorhersagen und Daten B auswerten.','Combine energy/force balances for specific charge with units; predict independent U/I variations and evaluate B.','Verdopplung von I verdoppelt r; die Energiegleichung wird nicht benötigt.'),('Zusätzlich unabhängig bekanntes |e| als notwendige Information benennen und daraus m berechnen; Verhältnis nicht als Masse ausgeben.','Identify independent |e| as necessary added information and calculate m without confusing ratio and mass.','1,758·10¹¹ C/kg ist bereits die gemessene Elektronenmasse.')],['magnetic-motion'],[{'calculation':'400/(.001**2*.0477**2)','expected':400/(.001**2*.0477**2),'unit':'C/kg'},{'calculation':'900/(.001**2*.0715**2)','expected':900/(.001**2*.0715**2),'unit':'C/kg'},{'calculation':'math.sqrt(450/200)','expected':1.5}])

add('cyclotron-synchrotron-comparison','Prüfungsaufgabe: Kreisbeschleuniger anhand von Betriebsdaten beurteilen','Assessment: Evaluate circular accelerators from operating data',[1],
'''**Material:** Alle Tabelleneinträge sind schematische Modellwerte derselben positiv geladenen, nichtrelativistischen Ionensorte (m₀,+e); p₀=|q|·(1,0 T)·(0,40 m). HF bezeichnet die Hochfrequenzbeschleunigung in elektrischen Spalten.

| Zyklus | p/p₀ | Anlage A: B | A: Radius | A: HF | Anlage B: B | B: Radius | B: HF |
|---|---:|---:|---:|---|---:|---:|---|
| 1 | 1 | 1,0 T | 0,40 m | f₀ fest | 1,0 T | 0,40 m | passende Phase |
| 2 | 2 | 1,0 T | 0,80 m | f₀ fest | 2,0 T | 0,40 m | passende Phase/Taktung |
| 3 | 3 | 1,0 T | 1,20 m | f₀ fest | 3,0 T | 0,40 m | passende Phase/Taktung |

**A:** Ordne idealisiertes Zyklotron und Synchrotron zu. Begründe mit p=|q|Br und T=2πm/(|q|B). Erkläre getrennt, wo Energie zugeführt und wo nur die Bahn geführt wird; begründe feste Zyklotrontaktung und wachsenden Radius.

**B:** Eine neue Ionensorte hat q=+2e und m=4m₀. Für ihre Zielenergie sei bereits der nötige Zielimpuls p_Z/|q|=1,00 T·m ermittelt. Eine Ringanlage hat maximalen Radius 0,50 m und maximales B=1,50 T. Prüfe beide Prinzipien gegen diese Grenzen. Welche maximale magnetische Steifigkeit Br ist möglich, welche Änderung wäre mindestens nötig? Wenn ein größerer Ring verfügbar wäre und die Geschwindigkeit relativistisch würde: beurteile die feste Taktung eines unveränderten idealen Zyklotrons, die Umstellung auf die neue Ionensorte und die notwendigen Anpassungen eines Synchrotrons. Nenne eine verbleibende Betriebsgrenze.''',
'''**Material:** All entries are schematic values for one positive, nonrelativistic ion species (m₀,+e); p₀=|q|×(1.0 T)×(0.40 m). RF accelerates in electric gaps.

| Cycle | p/p₀ | A: B | A: radius | A: RF | B: B | B: radius | B: RF |
|---|---:|---:|---:|---|---:|---:|---|
| 1 | 1 | 1.0 T | 0.40 m | fixed f₀ | 1.0 T | 0.40 m | matched phase |
| 2 | 2 | 1.0 T | 0.80 m | fixed f₀ | 2.0 T | 0.40 m | matched phase/timing |
| 3 | 3 | 1.0 T | 1.20 m | fixed f₀ | 3.0 T | 0.40 m | matched phase/timing |

**A:** Identify ideal cyclotron and synchrotron using p=|q|Br and T=2πm/(|q|B). Explain energy supply versus magnetic steering, fixed cyclotron RF and increasing radius.

**B:** A new species has q=+2e, m=4m₀. Its required target rigidity is already known: p_Z/|q|=1.00 T·m. A ring allows at most radius 0.50 m and B=1.50 T. Test both principles against these limits; find maximum Br and a necessary hardware change. If a larger ring becomes available and the speed becomes relativistic, evaluate unchanged ideal-cyclotron RF, the species change, synchrotron adjustments and one remaining operating limitation.''',
'''A ist ideales Zyklotron: konstantes B und für dieselbe nichtrelativistische Sorte konstantes T/f, Radius proportional p. B ist Synchrotron: bei festem Radius B proportional p; HF-Phase/Taktung wird passend zur Teilchenbewegung gehalten. E-Felder verrichten Beschleunigungsarbeit, reine magnetische Bahnführung nicht. B: maximales Br=0,75 T·m<1,00 T·m, daher erreicht keines der Prinzipien innerhalb beider genannten Grenzen das Ziel. Bei r=0,50 m wäre B≥2,00 T nötig; bei B=1,50 T wäre r≥0,667 m nötig. Für neue Sorte ist m/|q| gegenüber (m₀,e) doppelt, T bei gleichem B doppelt und feste Resonanzfrequenz halbiert. Bei relativistischer Bewegung gilt T=2πγm/(|q|B): unverändertes ideales konstantes B/f verliert Synchronität. Synchrotron muss B mit p und HF-Phase/Taktung passend anpassen; bei v≈c kann die Frequenz nahezu konstant werden, ihre Phase bleibt zu synchronisieren. Begrenzungen: erreichbares B und Radius, Beschleunigungs-/HF-Leistung, Synchronisationsgenauigkeit; hohe Energien sind nicht automatisch möglich.''',
'''A is an ideal cyclotron: fixed B and, for one nonrelativistic species, fixed T/f with radius proportional to p. B is a synchrotron: at fixed radius B rises with p and RF phase/timing follows particle motion. Electric fields supply energy; magnetic steering does no work. B: maximum Br=0.75 T·m<1.00 T·m, so neither principle reaches the target under both limits. At r=0.50 m one needs B≥2.00 T; at 1.50 T, r≥0.667 m. Relative to (m₀,e), the new species doubles m/|q|, doubles T and halves nonrelativistic resonant frequency at the same B. At relativistic speeds T=2πγm/(|q|B), so an unchanged ideal constant-B/f cyclotron loses synchronism. A synchrotron adjusts B with p and maintains RF phase/timing; near c frequency may become nearly constant while phase synchronisation remains necessary. Field/radius limits, RF power and timing remain operating constraints.''',
 [('Elektrische Energiezufuhr und arbeitsfreie magnetische Bahnführung für beide Anlagen sowie neue Ionensorte getrennt begründen.','Separate electric energy supply and work-free magnetic steering for both machines and the new species.','Das stärkere Synchrotronmagnetfeld liefert selbst den gesamten Energiezuwachs.'),('Feste nichtrelativistische Zyklotrontaktung aus m/|q| und wachsender Radius; neue Ionensorte und relativistische Synchronitätsgrenze.','Fixed nonrelativistic cyclotron timing and growing radius; new-species scaling and relativistic synchronism limit.','Die feste Zyklotronfrequenz gilt für jede Ionensorte und beliebig nahe c.'),('Synchrotron-B/Phasenanpassung und datenbegrenzte Wahl: Ziel unter gegebenen Br-Grenzen unmöglich, nötige Änderung explizit.','Synchrotron B/phase coordination and data-limited feasibility: target impossible under Br limits, required change explicit.','Ein Synchrotron erreicht bei gleichem maximalem Br jedes beliebige p, weil der Radius konstant bleibt.')],['accelerators'],[{'calculation':'1.5*.5','expected':.75,'unit':'T m'},{'calculation':'1/.5','expected':2,'unit':'T'},{'calculation':'1/1.5','expected':2/3,'unit':'m'}])

add('friction-and-charge-conservation','Prüfungsaufgabe: Reibung, Wechselwirkung und Ladungsbilanz','Assessment: Friction, interaction and charge balance',[10,15],
'''**Material A – sichere vorbereitete Niedrigenergie-Beobachtungen:** Zwei gleiche leichte Kunststoffstreifen S₁/S₂ und zugehörige Tücher T₁/T₂ sind zunächst neutral. Ohne Reiben ist keine reproduzierbare gegenseitige Bewegung messbar. Danach wird jeder Streifen gleich oft mit seinem eigenen Tuch gerieben, vom Tuch getrennt und frei aufgehängt. S₁/S₂ bewegen sich auseinander, S₁/T₁ aufeinander zu. Keine Netzspannung oder Hochspannungsquelle verwenden.

**A:** Gib eine prüfbare Frage, eine unbehandelte Kontrolle und drei konstant zu haltende Bedingungen an. Trenne beobachtete Bewegung und Deutung als Kraft/Ladungstrennung. Zeichne für beide Körper jedes Paars die Kräfte und erläutere, welche Ladungszeichen sicher erschließbar sind. Das abgeschlossene Paar S₁+T₁ startet mit 0 nC; S₁ hat danach −6 nC: bestimme T₁ und erläutere die Gesamtbilanz.

**B:** Ein unbekannter Körper U wird von einer positiven Referenz angezogen, von einer negativen Referenz abgestoßen und zieht zunächst neutrales Papier an. Erkläre Ladungsart, Kräfte auf beide Partner und Aussagegrenzen. Drei Körper im isolierten Behälter haben vorher +5, −2, 0 nC und nachher +1, +6, x nC: bestimme x. Eine zusätzliche Kugel verliert durch Erdung ihre +4 nC. Beurteile „Ladung wurde vernichtet“ für die Kugel allein und das erweiterte System Kugel+Leitung+Erde.''',
'''**Material A – prepared safe low-energy observations:** Identical light plastic strips S₁/S₂ and their cloths T₁/T₂ start neutral. Before rubbing there is no reproducible mutual movement. Each strip is rubbed the same number of times with its own cloth, separated and freely suspended. S₁/S₂ move apart; S₁/T₁ move together. Do not use mains or a high-voltage source.

**A:** State a testable question, an untreated control and three controlled conditions. Separate observed motion from force/charge-separation interpretation. Draw forces on both members of each pair and explain which charge signs are inferable. The closed S₁+T₁ pair starts at 0 nC; afterwards S₁ is −6 nC: determine T₁ and explain total balance.

**B:** Unknown U is attracted by a positive reference, repelled by a negative reference and attracts initially neutral paper. Explain U's charge, both partners' force directions and inference limits. Three bodies in an isolated enclosure change from +5, −2, 0 nC to +1, +6, x nC: find x. A further sphere loses +4 nC on grounding. Evaluate “charge was destroyed” for the sphere alone and for sphere+lead+Earth.''',
'''A: z.B. Frage, ob standardisiertes Reiben die Wechselwirkung gegenüber unbehandelten Paaren ändert; kontrollieren Materialpaar/Reibanzahl, Anfangsneutralität, Abstand/Aufhängung und Entladung zwischen Wiederholungen. Beobachtet werden Bewegungen, daraus entgegengesetzte Kräfte entlang der Verbindung erschlossen. Streifen stoßen sich bei gleichartiger Ladung ab, Streifen/Tuch ziehen sich an; absolute Vorzeichen folgen daraus allein nicht. Ladungstrennung, keine Erzeugung von Nettoladung. Bei gemessenem S₁=−6 nC ist T₁=+6 nC. B: Abstoßung von bekannter negativer Referenz belegt U negativ; Anziehung zur positiven ist konsistent. Papieranziehung beweist kein positives Papier, ein neutraler Körper kann polarisiert/umgeordnet angezogen werden. Kräfte auf beide Partner entgegengesetzt. Gesamt vorher +3 nC, daher x=−4 nC. Kugel ist beim Erden offen; Elektronenfluss zur positiven Kugel gleicht ihren Elektronenmangel aus. Im erweiterten abgeschlossenen System erfolgt Umverteilung, keine Vernichtung; Erde/Leitung übernehmen die entgegengesetzte Ladungsänderung.''',
'''A: ask whether standardised rubbing changes interaction relative to untreated controls; hold material/rub count, initial neutrality, separation/suspension and resetting between repeats fixed. Motions are observed, opposing forces along the connecting line are inferred. Strip repulsion supports like charge; strip/cloth attraction alone does not identify absolute signs. Rubbing separates charge rather than creating net charge. Measured S₁=−6 nC implies T₁=+6 nC. B: repulsion from a negative reference establishes U negative; positive-reference attraction is consistent. Attraction of neutral paper does not prove positive paper. Both partners feel opposite forces. Initial total +3 nC gives x=−4 nC. Grounding makes the sphere an open subsystem: electrons enter the positive sphere. Sphere+lead+Earth redistributes conserved charge, with an opposite environmental charge change.''',
 [('Kontrollierter phänomenologischer Vorher/Nachher-Vergleich mit beiden getrennten Reibpartnern, Beobachtung/Deutung und neuen Referenzbeobachtungen.','Controlled before/after comparison of both separated rubbing partners, observation/inference and fresh reference observations.','Ohne Kontrolle wird nur behauptet, Reiben erzeuge neue Nettoladung.'),('Anziehung/Abstoßung und Kräfte auf beide Partner samt Grenzen der Vorzeichenbestimmung einschließlich neutralem Papier.','Attraction/repulsion and forces on both partners with charge-sign inference limits, including neutral paper.','Jeder angezogene Körper ist zwingend entgegengesetzt geladen; Papier ist daher positiv.'),('Algebraische Gesamtladung und fehlende Teilgröße für unabhängige Zweikörper- und Dreikörperbilanzen korrekt.','Algebraic total charge and missing part for independent two-/three-body balances.','Nach Reiben darf die abgeschlossene Summe beliebig von null abweichen.'),('Offene Teilgrenze versus erweitertes abgeschlossenes System und konkreter Ladungstransfer bei Erdung, ohne Vernichtung/Erzeugung.','Open subsystem versus extended closed system and actual grounding transfer without destruction/creation.','Die +4 nC verschwinden aus dem Universum, weil die Kugel danach neutral ist.')],['charge'],[{'calculation':'5-2-1-6','expected':-4,'unit':'nC'}])

